<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';$p=db();$page=$_GET['page']??'home';
function view(string $title,string $html):void{$u=user();$m=flash();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($title)?> | AMIVON PAY</title><style>
:root{--n:#071a33;--b:#173b67;--g:#d8ad45;--bg:#f3f6fb;--line:#e3e9f1}*{box-sizing:border-box}body{margin:0;background:var(--bg);font:15px system-ui;color:#172338}header{background:linear-gradient(110deg,var(--n),var(--b));color:white;padding:17px max(18px,calc((100% - 1050px)/2);display:flex;justify-content:space-between;gap:14px;flex-wrap:wrap}.brand{font-size:21px;font-weight:900}.brand b,.gold{color:var(--g)}nav{display:flex;gap:14px;flex-wrap:wrap}nav a{color:white;font-size:13px}main{max-width:1050px;margin:25px auto;padding:0 17px}.hero{background:linear-gradient(120deg,#091d38,#1b416d);color:white;padding:30px;border-radius:20px}.hero h1{font-size:clamp(28px,5vw,42px);margin:8px 0}.hero p{color:#d4dfed}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:15px;margin:16px 0}.card{background:white;border:1px solid var(--line);border-radius:16px;padding:19px}.muted{color:#718096;font-size:13px}.metric{font-size:29px;font-weight:850}.btn{display:inline-block;background:var(--g);color:#172338;border:0;border-radius:10px;padding:12px 16px;font-weight:800;cursor:pointer}.alt{background:#edf2f8}form{display:grid;gap:12px}label{font-weight:700;font-size:13px}input{padding:12px;border:1px solid #d7dfeb;border-radius:9px;font:inherit;width:100%}table{border-collapse:collapse;width:100%;font-size:13px}td,th{text-align:left;padding:11px 8px;border-bottom:1px solid var(--line)}.notice{padding:12px;border-radius:10px;background:#eaf0f8;margin-bottom:15px}.success{background:#e5f7ee;color:#126c40}.error{background:#fff0ed;color:#a33}.pill{background:#edf2f8;border-radius:20px;padding:4px 8px;font-size:11px}footer{text-align:center;color:#718096;padding:28px;font-size:12px}@media(max-width:600px){header{padding:15px}.hero{padding:22px}table{display:block;overflow:auto;white-space:nowrap}}</style></head><body><header><a class="brand" href="/">AMIVON <b>PAY</b></a><nav><?php if($u):?><a href="/?page=dashboard">Dashboard</a><a href="/?page=deposit">Deposit</a><a href="/?page=transactions">Transactions</a><?php if($u['role']==='admin'):?><a href="/?page=admin">Admin</a><?php endif?><a href="/?page=logout">Sign out</a><?php else:?><a href="/?page=login">Sign in</a><a href="/?page=register">Register</a><?php endif?></nav></header><main><?php if($m):?><div class="notice <?=h($m[1])?>"><?=h($m[0])?></div><?php endif?><?=$html?></main><footer>AMIVON PAY · AMIVON ENTERPRISES · Paysasa TEST</footer></body></html><?php}
if($page==='logout'){session_destroy();header('Location: /');exit;}
if(in_array($page,['register','login'],true)&&$_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if($page==='register'){try{$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pw=(string)($_POST['password']??'');if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<10)throw new RuntimeException('Enter your name, valid email and password (10+ characters).');$q=$p->prepare('INSERT INTO users(name,email,password_hash,created_at) VALUES(?,?,?,?)');$q->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT),date('c')]);$id=(int)$p->lastInsertId();$_SESSION['user']=['id'=>$id,'name'=>$name,'email'=>$email,'role'=>'customer'];header('Location: /?page=dashboard');exit;}catch(Throwable $e){msg($e->getMessage(),'error');header('Location: /?page=register');exit;}}else{$q=$p->prepare('SELECT * FROM users WHERE email=?');$q->execute([strtolower(trim($_POST['email']??''))]);$x=$q->fetch();if($x&&password_verify((string)($_POST['password']??''),$x['password_hash'])){session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$x['id'],'name'=>$x['name'],'email'=>$x['email'],'role'=>$x['role']];header('Location: /?page=dashboard');exit;}msg('Invalid email or password.','error');header('Location: /?page=login');exit;}}
if($page==='deposit'&&$_SERVER['REQUEST_METHOD']==='POST'){$u=need_user();check_csrf();try{$v=(string)($_POST['amount']??'');if(!preg_match('/^\d+(\.\d{1,2})?$/',$v))throw new RuntimeException('Enter a valid amount.');$amount=(int)round((float)$v*100);if($amount<100)throw new RuntimeException('Minimum deposit is KES 1.00.');$biz=ev('PAYSASA_BUSINESS_ID');if(!$biz)throw new RuntimeException('Add PAYSASA_BUSINESS_ID in Render settings first.');$ref='AMP-'.strtoupper(bin2hex(random_bytes(6)));$q=$p->prepare("INSERT INTO transactions(user_id,amount_minor,currency,status,reference,description,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?)");$q->execute([$u['id'],$amount,'KES','creating',$ref,'AMIVON PAY wallet deposit',date('c'),date('c')]);$id=(int)$p->lastInsertId();$url=rtrim(ev('APP_URL','https://amivon-pay.onrender.com'),'/');$d=api('POST','/checkout/sessions',['amount'=>$amount,'currency'=>'KES','business_id'=>$biz,'description'=>'AMIVON PAY deposit '.$ref,'success_url'=>$url.'/?page=return&ref='.$ref,'cancel_url'=>$url.'/?page=dashboard','return_url'=>$url.'/?page=return&ref='.$ref,'callback_url'=>$url.'/?page=return&ref='.$ref,'allow_methods'=>['m_pesa','wallet'],'metadata'=>['amivon_reference'=>$ref,'user_id'=>(string)$u['id'],'purpose'=>'wallet_deposit']],true,$ref);$s=$d['session']??[];if(empty($s['id'])||empty($s['hosted_url']))throw new RuntimeException('Paysasa did not return a checkout URL.');$p->prepare('UPDATE transactions SET session_id=?,status=?,updated_at=? WHERE id=?')->execute([$s['id'],$s['status']??'pending',date('c'),$id]);header('Location: '.$s['hosted_url'],true,303);exit;}catch(Throwable $e){if(isset($id))$p->prepare("UPDATE transactions SET status='failed',updated_at=? WHERE id=?")->execute([date('c'),$id]);msg($e->getMessage(),'error');header('Location: /?page=deposit');exit;}}
if($page==='return'){$u=need_user();$q=$p->prepare('SELECT * FROM transactions WHERE reference=? AND user_id=?');$q->execute([(string)($_GET['ref']??''),$u['id']]);$t=$q->fetch();if(!$t||!$t['session_id']){msg('Payment reference not found.','error');header('Location: /?page=transactions');exit;}try{$d=api('GET','/checkout/sessions/'.rawurlencode($t['session_id']),null,false);settle($d['session']??[],(int)$t['id']);$q=$p->prepare('SELECT status FROM transactions WHERE id=?');$q->execute([$t['id']]);$st=$q->fetchColumn();msg($st==='completed'?'Payment confirmed; wallet credited.':'Payment status: '.($st?:'pending').'. Wallet credits only after confirmation.',$st==='completed'?'success':'info');}catch(Throwable $e){msg('Unable to verify yet: '.$e->getMessage(),'error');}header('Location: /?page=transactions');exit;}
if($page==='refresh'&&$_SERVER['REQUEST_METHOD']==='POST'){$u=need_user();check_csrf();$q=$p->prepare('SELECT * FROM transactions WHERE id=? AND user_id=?');$q->execute([(int)($_POST['id']??0),$u['id']]);$t=$q->fetch();if($t&&$t['session_id'])try{$d=api('GET','/checkout/sessions/'.rawurlencode($t['session_id']),null,false);settle($d['session']??[],(int)$t['id']);msg('Payment status refreshed.','success');}catch(Throwable $e){msg($e->getMessage(),'error');}else msg('Transaction not found.','error');header('Location: /?page=transactions');exit;}
if($page==='dashboard'){$u=need_user();$q=$p->prepare('SELECT * FROM transactions WHERE user_id=? ORDER BY id DESC LIMIT 5');$q->execute([$u['id']]);$rows=$q->fetchAll();ob_start();?><div class="hero"><div class="gold">AMIVON PAY WALLET</div><h1>Hello, <?=h($u['name'])?></h1><p>Your payments. Your business. Your control.</p><div class="muted" style="color:#d1ddec">Test wallet balance</div><div class="metric"><?=h(cash(bal((int)$u['id'])))?></div><a class="btn" href="/?page=deposit">Add money</a> <a class="btn alt" href="/?page=transactions">Transactions</a></div><div class="grid"><div class="card"><div class="muted">Currency</div><div class="metric">KES</div></div><div class="card"><div class="muted">Account</div><b><?=h($u['email'])?></b></div></div><div class="card"><h3>Recent activity</h3><?php if(!$rows):?><p class="muted">No transactions yet.</p><?php else:?><table><tr><th>Reference</th><th>Amount</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['reference'])?></td><td><?=h(cash((int)$r['amount_minor']))?></td><td><?=h($r['status'])?></td></tr><?php endforeach?></table><?php endif?></div><?php view('Dashboard',ob_get_clean());exit;}
if($page==='deposit'){need_user();ob_start();?><h1>Add money</h1><div class="card" style="max-width:520px"><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf())?>"><label>Amount (KES)</label><input type="number" name="amount" min="1" step=".01" placeholder="500.00" required><p class="muted">Paysasa test checkout. Wallet credit is applied only after a confirmed completed payment.</p><button class="btn">Continue to Paysasa checkout</button></form></div><?php view('Deposit',ob_get_clean());exit;}
if($page==='transactions'){$u=need_user();$q=$p->prepare('SELECT * FROM transactions WHERE user_id=? ORDER BY id DESC LIMIT 100');$q->execute([$u['id']]);$rows=$q->fetchAll();ob_start();?><h1>Transactions</h1><div class="card"><table><tr><th>Reference</th><th>Amount</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['reference'])?></td><td><?=h(cash((int)$r['amount_minor']))?></td><td><?=h($r['status'])?></td><td><?php if($r['session_id']&&$r['status']!=='completed'):?><form method="post" action="/?page=refresh"><input type="hidden" name="_csrf" value="<?=h(csrf())?>"><input type="hidden" name="id" value="<?=h((string)$r['id'])?>"><button class="btn alt">Refresh</button></form><?php else:?>—<?php endif?></td></tr><?php endforeach?></table></div><?php view('Transactions',ob_get_clean());exit;}
if($page==='admin'){$u=need_admin();$stats=$p->query("SELECT COUNT(*) total,COALESCE(SUM(CASE WHEN status='completed' THEN amount_minor ELSE 0 END),0) volume FROM transactions")->fetch();$customers=(int)$p->query("SELECT COUNT(*) FROM users WHERE role='customer'")->fetchColumn();$rows=$p->query('SELECT t.*,u.name,u.email FROM transactions t JOIN users u ON u.id=t.user_id ORDER BY t.id DESC LIMIT 100')->fetchAll();ob_start();?><h1>Admin dashboard <span class="pill">TEST MODE</span></h1><div class="grid"><div class="card">Customers<div class="metric"><?=$customers?></div></div><div class="card">Transactions<div class="metric"><?=h((string)$stats['total'])?></div></div><div class="card">Confirmed volume<div class="metric"><?=h(cash((int)$stats['volume']))?></div></div></div><div class="card"><h3>Recent transactions</h3><table><tr><th>Customer</th><th>Reference</th><th>Amount</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['name'])?><br><?=h($r['email'])?></td><td><?=h($r['reference'])?></td><td><?=h(cash((int)$r['amount_minor']))?></td><td><?=h($r['status'])?></td></tr><?php endforeach?></table></div><?php view('Admin',ob_get_clean());exit;}
if($page==='login'||$page==='register'){$reg=$page==='register';ob_start();?><div class="card" style="max-width:460px;margin:20px auto"><h1><?=$reg?'Create account':'Sign in'?></h1><form method="post"><input type="hidden" name="_csrf" value="<?=h(csrf())?>"><?php if($reg):?><label>Full name</label><input name="name" required><?php endif?><label>Email</label><input type="email" name="email" required><label>Password</label><input type="password" name="password" minlength="<?=$reg?10:1?>" required><button class="btn"><?=$reg?'Create account':'Sign in'?></button></form></div><?php view($reg?'Register':'Login',ob_get_clean());exit;}
ob_start();?><div class="hero"><div class="gold">AMIVON ENTERPRISES PRESENTS</div><h1>Payments made <span class="gold">simpler.</span></h1><p>A digital wallet and checkout experience powered by Paysasa.</p><a class="btn" href="/?page=register">Get started</a> <a class="btn alt" href="/?page=login">Sign in</a></div><div class="grid"><div class="card"><h3>M-Pesa checkout</h3><p class="muted">Secure Paysasa hosted payment flow.</p></div><div class="card"><h3>Digital wallet</h3><p class="muted">View confirmed deposit balance and ledger.</p></div><div class="card"><h3>Transactions</h3><p class="muted">Track references and refresh pending payments.</p></div></div><?php view('Home',ob_get_clean());
